const etapaData = $('Consultar - ETAPA').item.json;
const eventoData = $('Consultar - EVENTO').item.json;
const rubinhoData = $('Consultar - RUBINHO').item.json;

const lead = (etapaData.items && etapaData.items[0]) ? etapaData.items[0] : (Array.isArray(etapaData) ? etapaData[0] : etapaData);
const event = Array.isArray(eventoData) ? eventoData[0] : eventoData;
const rubinho = Array.isArray(rubinhoData) ? rubinhoData[0] : rubinhoData;

return {
  lead: {
    id: lead.id || null,
    name: lead.name || null,
    phone: lead.phone || null,
    source: lead.source || null,
    client_id: lead.client_id || null,
    crm_stage_code: lead.crm_stage_code || null,
    crm_stage_name: lead.crm_stage_name || null,
    confirmation_status: lead.confirmation_status || null,
    handoff_required: lead.handoff_required ?? false,
    conversation_id: lead.conversation_id || null
  },
  event: {
    id: event.id || null,
    name: event.name || null,
    event_type: event.event_type || null,
    event_date: event.event_date || null,
    location: event.location || null,
    status: event.status || null
  },
  rubinho: {
    agent_id: rubinho.agent_id || null,
    name: rubinho.name || null,
    tone: rubinho.tone || null,
    delay_minutes: rubinho.delay_minutes || null,
    system_prompt: rubinho.system_prompt || null
  }
};
